cat > /tmp/repro.py <<'EOF'
from datalad.dochelpers import borrowkwargs

class A(object):
    def met1(self, kp1=None, kp2=1):
        """A.met1 doc

        Parameters
        ----------
        kp1 : None or int
          keyword parameter 1
        kp2 : int, optional
          something
        """
        pass

class B(object):
    @borrowkwargs(methodname=A.met1)
    def met_anothermet(self, **kwargs):
        pass

    @borrowkwargs(methodname=A.met1, exclude=['kp1'])
    def met_excl(self, **kwargs):
        pass

assert 'kp2 ' in B.met_anothermet.__doc__, B.met_anothermet.__doc__
assert 'kp1 ' in B.met_anothermet.__doc__
assert 'kp2 ' in B.met_excl.__doc__
assert 'kp1 ' not in B.met_excl.__doc__

# existing usage still works
class C(object):
    @borrowkwargs(A)
    def met1(self, bu, **kwargs):
        """C.met1 doc"""
        pass
    @borrowkwargs(A, 'met1')
    def met_nodoc(self, **kwargs):
        pass

assert 'kp2 ' in C.met1.__doc__
assert 'C.met1 doc' in C.met1.__doc__
assert 'kp1 ' in C.met_nodoc.__doc__
print("OK")
EOF
python /tmp/repro.py
